}

.uv-fcf button.on {
  color: #fff;
  box-shadow: inset 0 0 0 1.5px var(--c1),0 6px 16px color-mix(in srgb,var(--c1) 32%,transparent);
}

.uv-fcf button.on i {
  transform: scale(1);
}

