css:
.uv-fcg {
  --c1: #0071e3;
  --c2: #8ec5ff;
  --s: 16px;
  /* tamaño */
  --k: 1;
  /* velocidad */
  --fg: #1d1d1f;
  /* texto */
  --bg: #f5f5f7;
  /* fondo */
}

.uv-fcg {
  font-family: -apple-system,BlinkMacSystemFont,"SF Pro Text","Inter",system-ui,sans-serif;
  font-size: var(--s);
  color: var(--fg);
  -webkit-tap-highlight-color: transparent;
  display: flex;
  flex-wrap: wrap;
  gap: .6em;
  justify-content: center;
}

.uv-fcg button {
  font-family: -apple-system,BlinkMacSystemFont,"SF Pro Text","Inter",system-ui,sans-serif;
  font-size: var(--s);
  font-weight: 550;
  line-height: 1;
  padding: .72em 1.25em;
  border: 0;
  border-radius: 999px;
  cursor: pointer;
  background: transparent;
  color: var(--fg);
  position: relative;
  transition: color calc(0.32s / var(--k)) cubic-bezier(.25,.1,.25,1),transform calc(0.32s / var(--k)) cubic-bezier(.34,1.56,.64,1);
  background: var(--bg);
  box-shadow: inset 0 0 0 1.5px color-mix(in srgb,var(--fg) 12%,transparent);
}

.uv-fcg button::before {
  content: "";
  position: absolute;
  inset: -2px;
  border-radius: 999px;
  padding: 2px;
  background: conic-gradient(from 0deg,var(--c1),var(--c2),var(--c1));
  -webkit-mask: linear-gradient(#000 0 0) content-box,linear-gradient(#000 0 0);
  -webkit-mask-composite: xor;
  mask: linear-gradient(#000 0 0) content-box,linear-gradient(#000 0 0);
  mask-composite: exclude;
  opacity: 0;
  transition: opacity calc(0.3s / var(--k)) cubic-bezier(.25,.1,.25,1);
  animation: uv-fcg calc(3s / var(--k)) linear infinite;
}

.uv-fcg button.on::before {
  opacity: 1;
}

.uv-fcg button.on {
  color: var(--c1);
}

.uv-fcg button:hover {
  box-shadow: inset 0 0 0 1.5px color-mix(in srgb,var(--c1) 45%,transparent),0 0 18px color-mix(in srgb,var(--c1) 22%,transparent);
}

@keyframes uv-fcg {
  to {
    transform: rotate(1turn);
  }
}

