  font-family: -apple-system,BlinkMacSystemFont,"SF Pro Text","Inter",system-ui,sans-serif;
  font-size: var(--s);
  font-weight: 550;
  line-height: 1;
  padding: .72em 1.25em;
  border: 0;
  border-radius: 999px;
  cursor: pointer;
  background: transparent;
  color: var(--fg);
  position: relative;
  transition: color calc(0.32s / var(--k)) cubic-bezier(.25,.1,.25,1),transform calc(0.32s / var(--k)) cubic-bezier(.34,1.56,.64,1);
  display: inline-flex;
  align-items: center;
  gap: .5em;
  background: var(--bg);
  box-shadow: inset 0 0 0 1.5px color-mix(in srgb,var(--fg) 13%,transparent);
}

.uv-fdd .tg:hover {
  box-shadow: inset 0 0 0 1.5px var(--c1);
  color: var(--c1);
}

.uv-fdd .tg i {
  display: grid;
  place-items: center;
  transition: transform calc(0.35s / var(--k)) cubic-bezier(.34,1.56,.64,1));
}

.uv-fdd .tg svg {
  width: 1em;
  height: 1em;
}

.uv-fdd.open .tg i {
  transform: rotate(180deg);
}

.uv-fdd .mn {
  position: absolute;
  top: calc(100% + .5em);
  left: 0;
  min-width: 100%;
  display: flex;
  flex-direction: column;
  padding: .4em;
  border-radius: 1em;
