.uv-ftb {
  --c1: #0071e3;
  --c2: #8ec5ff;
  --s: 16px;
  /* tamaño */
  --k: 1;
  /* velocidad */
  --fg: #1d1d1f;
  /* texto */
  --bg: #f5f5f7;
  /* fondo */
}

.uv-ftb {
  font-family: -apple-system,BlinkMacSystemFont,"SF Pro Text","Inter",system-ui,sans-serif;
  font-size: var(--s);
  color: var(--fg);
  -webkit-tap-highlight-color: transparent;
  width: 24em;
  display: flex;
  flex-direction: column;
  gap: .8em;
}

.uv-ftb .rw {
  display: flex;
  gap: .5em;
  flex-wrap: wrap;
}

.uv-ftb .dd {
  position: relative;
}

.uv-ftb .tg {
  font-family: -apple-system,BlinkMacSystemFont,"SF Pro Text","Inter",system-ui,sans-serif;
  font-size: var(--s);
  font-weight: 550;
  line-height: 1;
  padding: .72em 1.25em;
  border: 0;
  border-radius: 999px;
  cursor: pointer;
  background: transparent;
  color: var(--fg);
  position: relative;
  transition: color calc(0.32s / var(--k)) cubic-bezier(.25,.1,.25,1),background calc(0.32s / var(--k)) cubic-bezier(.25,.1,.25,1),transform calc(0.32s / var(--k)) cubic-bezier(.34,1.56,.64,1);
  display: inline-flex;
  align-items: center;
  gap: .45em;
  font-size: calc(var(--s) * .88);
  background: var(--bg);
  box-shadow: inset 0 0 0 1.5px color-mix(in srgb,var(--fg) 13%,transparent);
}

.uv-ftb .tg:hover {
  color: var(--c1);
  box-shadow: inset 0 0 0 1.5px var(--c1);
}

.uv-ftb .tg svg {
  width: .95em;
  height: .95em;
}

.uv-ftb .tg i {
  display: grid;
  place-items: center;
  transition: transform calc(0.35s / var(--k)) cubic-bezier(.34,1.56,.64,1);
}

.uv-ftb .dd.open .tg i {
  transform: rotate(180deg);
}

.uv-ftb .dd.open .tg {
  color: var(--c1);
  box-shadow: inset 0 0 0 1.5px var(--c1);
}

.uv-ftb .mn {
  position: absolute;
  top: calc(100% + .4em);
  left: 0;
  min-width: 9em;
  display: flex;
  flex-direction: column;
  padding: .35em;
  border-radius: .9em;
  background: var(--bg);
  box-shadow: 0 16px 36px rgba(0,0,0,.16);
  transform-origin: top left;
  scale: .94;
  opacity: 0;
  pointer-events: none;
  transition: scale calc(0.3s / var(--k)) cubic-bezier(.34,1.56,.64,1),opacity calc(0.22s / var(--k)) cubic-bezier(.25,.1,.25,1);
  z-index: 3;
}

.uv-ftb .dd.open .mn {
  scale: 1;
  opacity: 1;
  pointer-events: auto;
}

.uv-ftb .mn button {
  font-family: -apple-system,BlinkMacSystemFont,"SF Pro Text","Inter",system-ui,sans-serif;
  font-size: var(--s);
  font-weight: 550;
  line-height: 1;
  padding: .72em 1.25em;
  border: 0;
  border-radius: 999px;
  cursor: pointer;
  background: transparent;
  color: var(--fg);
  position: relative;
  transition: color calc(0.32s / var(--k)) cubic-bezier(.25,.1,.25,1),background calc(0.32s / var(--k)) cubic-bezier(.25,.1,.25,1),transform calc(0.32s / var(--k)) cubic-bezier(.34,1.56,.64,1);
  text-align: left;
  font-size: calc(var(--s) * .85);
  padding: .5em .7em;
  border-radius: .55em;
}

.uv-ftb .mn button:hover {
  background: color-mix(in srgb,var(--c1) 10%,transparent);
  color: var(--c1);
}

.uv-ftb .tags {
  display: flex;
  flex-wrap: wrap;
  gap: .4em;
  min-height: 2.2em;
  align-content: flex-start;
}

.uv-ftb .tags span {
  display: inline-flex;
  align-items: center;
  gap: .4em;
  padding: .45em .75em;
  border-radius: 999px;
  font-size: calc(var(--s) * .8);
  font-weight: 600;
  color: var(--c1);
  background: color-mix(in srgb,var(--c1) 13%,transparent);
  animation: uv-ftb-in calc(0.4s / var(--k)) cubic-bezier(.34,1.56,.64,1);
}

.uv-ftb .tags span.out {
  animation: uv-ftb-out calc(0.3s / var(--k)) cubic-bezier(.25,.1,.25,1) forwards;
}

.uv-ftb .tags svg {
  width: .8em;
  height: .8em;
  cursor: pointer;
  opacity: .7;
  transition: opacity calc(0.2s / var(--k)) cubic-bezier(.25,.1,.25,1),transform calc(0.3s / var(--k)) cubic-bezier(.34,1.56,.64,1);
}

.uv-ftb .tags svg:hover {
  opacity: 1;
  transform: scale(1.2);
}

@keyframes uv-ftb-in {
  from {
    scale: .5;
    opacity: 0;
  }
  to {
    scale: 1;
    opacity: 1;
  }
}

@keyframes uv-ftb-out {
  to {
    scale: .5;
    opacity: 0;
  }
}

