css:
.uv-fdy {
  --c1: #ff7a3d;
  --c2: #ffffff;
  --s: 16px;
  /* tamaño */
  --k: 1;
  /* velocidad */
  --fg: #1d1d1f;
  /* texto */
  --bg: #f5f5f7;
  /* fondo */
}

.uv-fdy {
  font-family: -apple-system,BlinkMacSystemFont,"SF Pro Text","Inter",system-ui,sans-serif;
  font-size: var(--s);
  color: var(--fg);
  -webkit-tap-highlight-color: transparent;
  border: 0;
  margin: 0;
  padding: 0;
  min-width: 0;
  width: 19em;
  padding: .9em;
  border-radius: 1.3em;
  background: color-mix(in srgb,var(--fg) 4%,var(--bg));
  box-shadow: 0 0 0 1px color-mix(in srgb,var(--fg) 9%,transparent),0 18px 40px -26px rgba(0,0,0,.4);
}

.uv-fdy legend {
  padding: 0;
  margin: 0 0 .8em;
  font-weight: 700;
  float: left;
  width: 100%;
}

.uv-fdy .sky {
  clear: both;
  --uv-fdy-a: #ffd7c2;
  --uv-fdy-b: #ffb3c7;
  --x: 20%;
  --y: 62%;
  position: relative;
  height: 6.5em;
  border-radius: .9em;
  overflow: hidden;
  background: linear-gradient(180deg,var(--uv-fdy-a),var(--uv-fdy-b));
  transition: --uv-fdy-a calc(0.8s / var(--k)) cubic-bezier(.25,.1,.25,1),--uv-fdy-b calc(0.8s / var(--k)) cubic-bezier(.25,.1,.25,1);
}

.uv-fdy .orb {
  position: absolute;
  left: var(--x);
  top: var(--y);
  width: 2.2em;
  height: 2.2em;
  margin: -1.1em;
  border-radius: 50%;
  background: radial-gradient(circle at 40% 35%,#fff,#ffe9a8 45%,#ffc24d);
  box-shadow: 0 0 1.5em .3em color-mix(in srgb,#ffd36e 70%,transparent);
  transition: left calc(0.9s / var(--k)) cubic-bezier(.22,1,.36,1),top calc(0.9s / var(--k)) cubic-bezier(.22,1,.36,1),background calc(0.6s / var(--k)) cubic-bezier(.25,.1,.25,1),box-shadow calc(0.6s / var(--k)) cubic-bezier(.25,.1,.25,1);
}

.uv-fdy .hz {
  position: absolute;
  left: 0;
  right: 0;
  bottom: 0;
  height: 30%;
  background: linear-gradient(180deg,transparent,color-mix(in srgb,#000 18%,transparent)),radial-gradient(120% 100% at 30% 100%,color-mix(in srgb,#000 22%,transparent) 50%,transparent 51%),radial-gradient(90% 90% at 85% 110%,color-mix(in srgb,#000 30%,transparent) 50%,transparent 51%);
}

.uv-fdy .op {
  display: grid;
  grid-template-columns: repeat(4,1fr);
  gap: .35em;
  margin-top: .6em;
}

.uv-fdy label {
  position: relative;
  cursor: pointer;
}

.uv-fdy input {
  position: absolute;
  opacity: 0;
  width: 1px;
  height: 1px;
  margin: 0;
  pointer-events: none;
}

.uv-fdy label span {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: .3em;
  padding: .55em 0;
  border-radius: .7em;
  font-size: .75em;
  font-weight: 600;
  color: color-mix(in srgb,var(--fg) 55%,transparent);
  transition: all calc(0.3s / var(--k)) cubic-bezier(.25,.1,.25,1);
}

.uv-fdy label svg {
  width: 1.6em;
  height: 1.6em;
}

.uv-fdy label:hover span {
  color: var(--fg);
  background: color-mix(in srgb,var(--fg) 6%,transparent);
}

.uv-fdy input:checked + span {
  color: #fff;
  background: var(--c1);
  box-shadow: 0 .4em 1em -.5em var(--c1);
}

.uv-fdy input:focus-visible + span {
  outline: 2px solid var(--c1);
  outline-offset: 3px;
}

.uv-fdy:has(label:nth-of-type(1) input:checked) .sky {
  --uv-fdy-a: #ffd7c2;
  --uv-fdy-b: #ffb3c7;
  --x: 20%;
  --y: 62%;
}

.uv-fdy:has(label:nth-of-type(2) input:checked) .sky {
  --uv-fdy-a: #8fd3ff;
  --uv-fdy-b: #d8f1ff;
  --x: 50%;
  --y: 18%;
}

.uv-fdy:has(label:nth-of-type(3) input:checked) .sky {
  --uv-fdy-a: #ff9d5c;
  --uv-fdy-b: #ffd36e;
  --x: 80%;
  --y: 58%;
}

.uv-fdy:has(label:nth-of-type(4) input:checked) .sky {
  --uv-fdy-a: #1d2a5a;
  --uv-fdy-b: #3b4c8f;
  --x: 50%;
  --y: 22%;
}

.uv-fdy:has(label:nth-of-type(4) input:checked) .orb {
  background: radial-gradient(circle at 60% 40%,#fdfcf5,#d9dce8 60%,#aeb3c7);
  box-shadow: 0 0 1.4em .1em rgba(220,228,255,.45);
}

.uv-fdy:has(label:nth-of-type(4) input:checked) .sky::before {
  content: "";
  position: absolute;
  inset: 0;
  background: radial-gradient(1px 1px at 12% 20%,#fff 60%,transparent),radial-gradient(1px 1px at 28% 45%,#fff 60%,transparent),radial-gradient(1.5px 1.5px at 70% 25%,#fff 60%,transparent),radial-gradient(1px 1px at 88% 50%,#fff 60%,transparent),radial-gradient(1px 1px at 40% 15%,#fff 60%,transparent),radial-gradient(1px 1px at 60% 55%,#fff 60%,transparent);
}

@property --uv-fdy-a {
  syntax: "<color>";
  inherits: true;
  initial-value: #ffd7c2;
}

@property --uv-fdy-b {
  syntax: "<color>";
  inherits: true;
  initial-value: #ffb3c7;
}

