css:
.uv-frb {
  --c1: #f59e0b;
  --c2: #fff3d6;
  --s: 16px;
  /* tamaño */
  --k: 1;
  /* velocidad */
  --fg: #1d1d1f;
  /* texto */
  --bg: #f5f5f7;
  /* fondo */
}

.uv-frb {
  font-family: -apple-system,BlinkMacSystemFont,"SF Pro Text","Inter",system-ui,sans-serif;
  font-size: var(--s);
  color: var(--fg);
  -webkit-tap-highlight-color: transparent;
  border: 0;
  margin: 0;
  padding: 0;
  min-width: 0;
  width: 17em;
}

.uv-frb legend {
  padding: 0;
  margin: 0 0 .8em;
  font-weight: 700;
}

.uv-frb label {
  position: relative;
  display: grid;
  grid-template-columns: 2.4em 1fr 2.4em;
  align-items: center;
  gap: .6em;
  padding: .4em .5em;
  border-radius: .6em;
  cursor: pointer;
  transition: background calc(0.25s / var(--k)) cubic-bezier(.25,.1,.25,1);
}

.uv-frb input {
  position: absolute;
  opacity: 0;
  width: 1px;
  height: 1px;
  margin: 0;
  pointer-events: none;
}

.uv-frb .st {
  display: flex;
  align-items: center;
  gap: .2em;
  font-weight: 700;
  font-variant-numeric: tabular-nums;
}

.uv-frb .st svg {
  width: .95em;
  height: .95em;
  fill: color-mix(in srgb,var(--fg) 24%,transparent);
  transition: fill calc(0.25s / var(--k)) cubic-bezier(.25,.1,.25,1);
}

.uv-frb .br {
  height: .5em;
  border-radius: 1em;
  background: color-mix(in srgb,var(--fg) 6%,transparent);
  overflow: hidden;
}

.uv-frb .br i {
  display: block;
  width: var(--w);
  height: 100%;
  border-radius: inherit;
  background: color-mix(in srgb,var(--fg) 22%,transparent);
  transition: background calc(0.3s / var(--k)) cubic-bezier(.25,.1,.25,1);
}

.uv-frb .n {
  font-size: .8em;
  text-align: right;
  font-variant-numeric: tabular-nums;
  color: color-mix(in srgb,var(--fg) 55%,transparent);
}

.uv-frb label:hover {
  background: color-mix(in srgb,var(--fg) 6%,transparent);
}

.uv-frb label:has(input:checked) {
  background: var(--c2);
}

.uv-frb label:has(input:checked) .br i {
  background: var(--c1);
}

.uv-frb label:has(input:checked) .st svg {
  fill: var(--c1);
}

.uv-frb label:has(input:checked) .n {
  color: color-mix(in srgb,var(--c1) 60%,var(--fg));
}

.uv-frb label:has(input:focus-visible) {
  outline: 2px solid var(--c1);
  outline-offset: 3px;
}

