}

.uvq05-xy .pad:focus-visible {
  outline: 2px solid var(--c1);
  outline-offset: 3px;
}

.uvq05-xy .ax {
  position: absolute;
  font-size: .58em;
  font-weight: 700;
  letter-spacing: .12em;
  text-transform: uppercase;
  color: rgba(255,255,255,.5);
  pointer-events: none;
}

.uvq05-xy .ax.t {
  top: .8em;
  left: 50%;
  translate: -50% 0;
}

.uvq05-xy .ax.b {
  bottom: .8em;
  left: 50%;
  translate: -50% 0;
}

.uvq05-xy .ax.l {
  left: .9em;
  top: 50%;
  translate: 0 -50%;
}

.uvq05-xy .ax.r {
  right: .9em;
  top: 50%;
  translate: 0 -50%;
}

.uvq05-xy .cx,.uvq05-xy .cy {
  position: absolute;
  background: color-mix(in srgb,var(--c1) 55%,transparent);
