  width: 1px;
  left: calc(var(--x) * 100%);
}

.uvq05-xy .cy {
  left: 0;
  right: 0;
  height: 1px;
  top: calc((1 - var(--y)) * 100%);
}

.uvq05-xy .pt {
  position: absolute;
  left: calc(var(--x) * 100%);
