}

.uvq05-xy .pad.is-drag .pt,.uvq05-xy .pad.is-drag .cx,.uvq05-xy .pad.is-drag .cy {
  transition: none;
}

.uvq05-xy .pad:active .pt {
  transform: scale(.85);
}

