  letter-spacing: .06em;
  text-transform: uppercase;
  color: #6b6862;
}

.uvq05-xy .rd b {
  min-width: 3ch;
  color: #232323;
}

@keyframes uvq05-xyp {
  from {
    transform: scale(.6);
    opacity: 1;
  }
  to {
    transform: scale(2.2);
    opacity: 0;
  }
}

@media (prefers-reduced-motion:reduce) {
  .uvq05-xy,.uvq05-xy *,.uvq05-xy *::before,.uvq05-xy *::after {
    animation-duration: .01ms!important;
    animation-iteration-count: 1!important;
    transition-duration: .01ms!important;
  }
}

