.uvq05-wt {
  font-family: -apple-system,BlinkMacSystemFont,"SF Pro Text","Inter",system-ui,sans-serif;
  font-size: var(--s);
  color: var(--fg);
  -webkit-tap-highlight-color: transparent;
  border: 0;
  margin: 0;
  padding: 0;
  min-width: 0;
  position: relative;
  width: 18em;
  padding: 1em 1em 1.1em 2.3em;
  border-radius: .4em;
  color: #2b2b2b;
  background: linear-gradient(90deg,transparent 1.5em,rgba(220,70,70,.5) 1.5em calc(1.5em + 1px),transparent 0),repeating-linear-gradient(transparent 0 1.55em,rgba(70,110,190,.22) 1.55em calc(1.55em + 1px)),var(--c2);
  box-shadow: 0 1.2em 2.2em -1.3em rgba(0,0,0,.5),inset 0 0 0 1px rgba(0,0,0,.06);
  counter-reset: uvq05-wt;
}

.uvq05-wt legend {
  float: left;
  width: 100%;
