  font: 700 1.15em "Bradley Hand","Segoe Print","Marker Felt","Comic Sans MS",cursive;
}

.uvq05-wt .ts {
  clear: both;
  display: flex;
  flex-wrap: wrap;
  gap: .75em .55em;
}

.uvq05-wt label {
  position: relative;
  cursor: pointer;
  filter: drop-shadow(0 .4em .3em rgba(0,0,0,.2));
  transition: filter calc(0.35s / var(--k)) cubic-bezier(.25,.1,.25,1);
}

.uvq05-wt input {
  position: absolute;
  opacity: 0;
  width: 1px;
  height: 1px;
  margin: 0;
  pointer-events: none;
}

.uvq05-wt input:checked {
  counter-increment: uvq05-wt;
}

.uvq05-wt .tp {
  display: block;
  padding: .45em 1.05em;
