  clip-path: polygon(100.0% 0.0%,96.1% 16.7%,97.9% 33.3%,95.9% 50.0%,97.5% 66.7%,99.4% 83.3%,95.1% 100.0%,6.3% 100.0%,4.0% 83.3%,2.9% 66.7%,2.4% 50.0%,0.3% 33.3%,1.6% 16.7%,1.6% 0.0%);
  background: var(--pt),var(--tc);
  opacity: .55;
  transform: translateY(-.25em) rotate(calc(var(--r) * 2.4));
  transition: transform calc(0.45s / var(--k)) cubic-bezier(.34,1.56,.64,1),opacity calc(0.3s / var(--k)) cubic-bezier(.25,.1,.25,1);
}

.uvq05-wt label:nth-of-type(1) {
  --tc: #7fc8c2;
  --pt: repeating-linear-gradient(90deg,rgba(255,255,255,.45) 0 .35em,transparent .35em .7em);
}

.uvq05-wt label:nth-of-type(2) {
  --tc: #f4a6a0;
  --pt: radial-gradient(rgba(255,255,255,.75) 22%,transparent 25%) 0 0/.6em .6em;
}

.uvq05-wt label:nth-of-type(3) {
  --tc: #f6d365;
  --pt: linear-gradient(rgba(0,0,0,.09) 1px,transparent 1px) 0 0/.5em .5em,linear-gradient(90deg,rgba(0,0,0,.09) 1px,transparent 1px) 0 0/.5em .5em;
}

.uvq05-wt label:nth-of-type(4) {
  --tc: #b8a1e3;
  --pt: repeating-linear-gradient(45deg,rgba(255,255,255,.42) 0 .2em,transparent .2em .55em);
}

.uvq05-wt label:nth-of-type(5) {
  --tc: #9cc5f0;
  --pt: linear-gradient(45deg,rgba(255,255,255,.38) 25%,transparent 25% 75%,rgba(255,255,255,.38) 75%) 0 0/.7em .7em,linear-gradient(45deg,rgba(255,255,255,.38) 25%,transparent 25% 75%,rgba(255,255,255,.38) 75%) .35em .35em/.7em .7em;
}

.uvq05-wt label:nth-of-type(6) {
  --tc: #a8d5a2;
  --pt: radial-gradient(circle at 50% 100%,transparent .22em,rgba(255,255,255,.55) .23em .32em,transparent .33em) 0 0/.7em .45em;
}

.uvq05-wt label:hover .tp {
  transform: translateY(-.4em) rotate(calc(var(--r) * 3));
}

.uvq05-wt label:active .tp {
  transform: scale(.94) rotate(var(--r));
}

.uvq05-wt label:has(input:checked) {
  filter: drop-shadow(0 .06em .06em rgba(0,0,0,.18));
}

.uvq05-wt input:checked+.tp {
  opacity: .9;
  transform: rotate(var(--r));
}

.uvq05-wt label:has(input:checked):hover .tp {
  transform: translateY(-.06em) rotate(var(--r));
}

.uvq05-wt label:has(input:focus-visible) {
  outline: 2px solid var(--c1);
  outline-offset: 4px;
  border-radius: .2em;
}

.uvq05-wt .ct {
  margin: 1em 0 0;
  font: 700 .9em "Bradley Hand","Segoe Print","Marker Felt","Comic Sans MS",cursive;
  color: #5a5246;
}

.uvq05-wt .n::before {
  content: counter(uvq05-wt);
  color: var(--c1);
}

@media (prefers-reduced-motion:reduce) {
  .uvq05-wt,.uvq05-wt *,.uvq05-wt *::before,.uvq05-wt *::after {
    animation-duration: .01ms!important;
    animation-iteration-count: 1!important;
    transition-duration: .01ms!important;
  }
}

