css:
.uvq05-fr {
  --c1: #f2b134;
  --c2: #15120f;
  --s: 16px;
  /* tamaño */
  --k: 1;
  /* velocidad */
  --fg: #1d1d1f;
  /* texto */
  --bg: #f5f5f7;
  /* fondo */
}

.uvq05-fr {
  font-family: -apple-system,BlinkMacSystemFont,"SF Pro Text","Inter",system-ui,sans-serif;
  font-size: var(--s);
  color: var(--fg);
  -webkit-tap-highlight-color: transparent;
  border: 0;
  margin: 0;
  padding: 0;
  min-width: 0;
  width: 19em;
}

.uvq05-fr legend {
  padding: 0;
  margin: 0 0 .8em;
  font-weight: 700;
}

.uvq05-fr .fm {
  position: relative;
  padding: .85em .45em;
  border-radius: .35em;
  background: var(--c2);
  box-shadow: 0 1em 2em -1.2em rgba(0,0,0,.6);
}

.uvq05-fr .fm::before,.uvq05-fr .fm::after {
  content: "";
  position: absolute;
  left: .45em;
  right: .45em;
  height: .38em;
  background: linear-gradient(90deg,#efe6d2 0 .5em,transparent .5em) 0 0/1em 100% repeat-x;
  opacity: .9;
}

.uvq05-fr .fm::before {
  top: .22em;
}

.uvq05-fr .fm::after {
  bottom: .22em;
}

.uvq05-fr .ph {
  position: relative;
  height: 8.6em;
  overflow: hidden;
  border-radius: .12em;
}

.uvq05-fr .ph>svg:first-child {
  display: block;
  width: 100%;
  height: 100%;
  transition: filter calc(0.6s / var(--k)) cubic-bezier(.25,.1,.25,1);
}

.uvq05-fr .tn {
  position: absolute;
  inset: 0;
  mix-blend-mode: soft-light;
  opacity: 0;
  transition: opacity calc(0.6s / var(--k)) cubic-bezier(.25,.1,.25,1),background calc(0.6s / var(--k)) cubic-bezier(.25,.1,.25,1);
}

.uvq05-fr .gr {
  position: absolute;
  left: -20%;
  top: -20%;
  width: 140%;
  height: 140%;
  opacity: .15;
  mix-blend-mode: overlay;
  pointer-events: none;
  animation: uvq05-frg calc(0.5s / var(--k)) steps(3) infinite;
  transition: opacity calc(0.6s / var(--k)) cubic-bezier(.25,.1,.25,1);
}

.uvq05-fr .rl {
  display: flex;
  justify-content: space-between;
  margin-top: 1em;
}

.uvq05-fr label {
  position: relative;
  display: flex;
  flex-direction: column;
  align-items: center;
  width: 3.5em;
  padding-top: .4em;
  cursor: pointer;
}

.uvq05-fr input {
  position: absolute;
  opacity: 0;
  width: 1px;
  height: 1px;
  margin: 0;
  pointer-events: none;
}

.uvq05-fr .cn {
  position: relative;
  width: 1.9em;
  height: 2.9em;
  transition: transform calc(0.45s / var(--k)) cubic-bezier(.34,1.56,.64,1);
}

.uvq05-fr .cn::before {
  content: "";
  position: absolute;
  left: 50%;
  top: -.3em;
  width: .55em;
  height: .32em;
  margin-left: -.27em;
  border-radius: .1em .1em 0 0;
  background: linear-gradient(90deg,#3a3a3a,#bbb 45%,#555);
}

.uvq05-fr .cp {
  position: absolute;
  left: -.08em;
  right: -.08em;
  top: 0;
  z-index: 1;
  height: .34em;
  border-radius: .12em;
  background: linear-gradient(90deg,#5c5c5c,#efefef 35%,#a0a0a0 65%,#4a4a4a);
}

.uvq05-fr .cp.b {
  top: auto;
  bottom: 0;
}

.uvq05-fr .bd {
  position: absolute;
  left: 0;
  right: 0;
  top: .3em;
  bottom: .3em;
  display: grid;
  place-items: center;
  background: linear-gradient(90deg,rgba(0,0,0,.4),rgba(255,255,255,.32) 28%,rgba(255,255,255,0) 52%,rgba(0,0,0,.45)),var(--b);
}

.uvq05-fr .bd b {
  font-size: .62em;
  font-weight: 900;
  color: #fff;
  letter-spacing: .04em;
  writing-mode: vertical-rl;
  transform: rotate(180deg);
}

.uvq05-fr .ld {
  position: absolute;
  left: 92%;
  top: .75em;
  width: 1em;
  height: 1.3em;
  background: linear-gradient(#e9dfca 0 0) .15em .12em/.2em .18em,linear-gradient(#e9dfca 0 0) .55em .12em/.2em .18em,linear-gradient(#e9dfca 0 0) .15em 1em/.2em .18em,linear-gradient(#e9dfca 0 0) .55em 1em/.2em .18em,#3b2a1e;
  background-repeat: no-repeat;
  clip-path: polygon(0 0,100% 18%,100% 100%,0 100%);
  transform-origin: left;
  transform: scaleX(0);
  transition: transform calc(0.45s / var(--k)) cubic-bezier(.22,1,.36,1);
}

.uvq05-fr .nm {
  margin-top: .5em;
  font-size: .62em;
  font-weight: 600;
  line-height: 1.15;
  text-align: center;
  color: color-mix(in srgb,var(--fg) 58%,transparent);
  transition: color calc(0.3s / var(--k)) cubic-bezier(.25,.1,.25,1);
}

.uvq05-fr label:hover .cn {
  transform: rotate(-5deg);
}

.uvq05-fr input:checked+.cn {
  transform: translateY(-.35em);
}

.uvq05-fr input:checked+.cn .ld {
  transform: scaleX(1);
}

.uvq05-fr input:checked~.nm {
  color: var(--fg);
  font-weight: 800;
}

.uvq05-fr label:active .cn {
  transform: scale(.92);
}

.uvq05-fr input:focus-visible+.cn {
  outline: 2px solid var(--c1);
  outline-offset: .4em;
  border-radius: .2em;
}

.uvq05-fr:has(label:nth-of-type(1) input:checked) .ph>svg:first-child {
  filter: sepia(.18) saturate(1.45) contrast(1.04) brightness(1.05);
}

.uvq05-fr:has(label:nth-of-type(1) input:checked) .tn {
  background: #ff8a2a;
  opacity: 0.32;
}

.uvq05-fr:has(label:nth-of-type(1) input:checked) .gr {
  opacity: 0.16;
}

.uvq05-fr:has(label:nth-of-type(2) input:checked) .ph>svg:first-child {
  filter: grayscale(1) contrast(1.35) brightness(.96);
}

.uvq05-fr:has(label:nth-of-type(2) input:checked) .tn {
  background: transparent;
  opacity: 0;
}

.uvq05-fr:has(label:nth-of-type(2) input:checked) .gr {
  opacity: 0.32;
}

.uvq05-fr:has(label:nth-of-type(3) input:checked) .ph>svg:first-child {
  filter: saturate(1.75) contrast(1.18);
}

.uvq05-fr:has(label:nth-of-type(3) input:checked) .tn {
  background: transparent;
  opacity: 0;
}

.uvq05-fr:has(label:nth-of-type(3) input:checked) .gr {
  opacity: 0.08;
}

.uvq05-fr:has(label:nth-of-type(4) input:checked) .ph>svg:first-child {
  filter: saturate(.85) brightness(1.06);
}

.uvq05-fr:has(label:nth-of-type(4) input:checked) .tn {
  background: #3b82f6;
  opacity: 0.5;
}

.uvq05-fr:has(label:nth-of-type(4) input:checked) .gr {
  opacity: 0.14;
}

.uvq05-fr:has(label:nth-of-type(5) input:checked) .ph>svg:first-child {
  filter: saturate(1.15) contrast(1.12) brightness(.92);
}

.uvq05-fr:has(label:nth-of-type(5) input:checked) .tn {
  background: #1d4ed8;
  opacity: 0.6;
}

.uvq05-fr:has(label:nth-of-type(5) input:checked) .gr {
  opacity: 0.26;
}

@keyframes uvq05-frg {
  0% {
    transform: translate(0,0);
  }
  33% {
    transform: translate(-4%,3%);
  }
  66% {
    transform: translate(3%,-2%);
  }
}

@media (prefers-reduced-motion:reduce) {
  .uvq05-fr,.uvq05-fr *,.uvq05-fr *::before,.uvq05-fr *::after {
    animation-duration: .01ms!important;
    animation-iteration-count: 1!important;
    transition-duration: .01ms!important;
  }
}

