.uvq05-ln {
  --c1: #e8a33d;
  --c2: #1b1d22;
  --s: 16px;
  /* tamaño */
  --k: 1;
  /* velocidad */
  --fg: #1d1d1f;
  /* texto */
  --bg: #f5f5f7;
  /* fondo */
}

.uvq05-ln {
  font-family: -apple-system,BlinkMacSystemFont,"SF Pro Text","Inter",system-ui,sans-serif;
  font-size: var(--s);
  color: var(--fg);
  -webkit-tap-highlight-color: transparent;
  display: flex;
  align-items: center;
  gap: 1em;
  width: 20em;
  counter-reset: uvq05-ln;
}

.uvq05-ln .lens {
  position: relative;
  flex: none;
  width: 9.4em;
  height: 9.4em;
  border-radius: 50%;
  background: radial-gradient(farthest-side,#0c0c0e calc(100% - 1.6em),transparent calc(100% - 1.6em + 1px)),repeating-conic-gradient(var(--c2) 0 2deg,color-mix(in srgb,var(--c2) 70%,#fff) 2deg 4deg);
  box-shadow: 0 1em 2em -1em rgba(0,0,0,.6),inset 0 0 0 1px rgba(255,255,255,.12);
}

.uvq05-ln .gw {
  position: absolute;
  inset: 1.5em;
  border-radius: 50%;
  overflow: hidden;
  box-shadow: inset 0 0 1em #000;
}

.uvq05-ln .gw>div,.uvq05-ln .gw div {
