css:
.uvq05-ch {
  --c1: #e23d28;
  --c2: #3aa655;
  --s: 16px;
  /* tamaño */
  --k: 1;
  /* velocidad */
  --fg: #1d1d1f;
  /* texto */
  --bg: #f5f5f7;
  /* fondo */
}

.uvq05-ch {
  font-family: -apple-system,BlinkMacSystemFont,"SF Pro Text","Inter",system-ui,sans-serif;
  font-size: var(--s);
  color: var(--fg);
  -webkit-tap-highlight-color: transparent;
  border: 0;
  margin: 0;
  padding: 0;
  min-width: 0;
  width: 16em;
  --w: 60%;
}

.uvq05-ch legend {
  padding: 0;
  margin: 0 0 .8em;
  font-weight: 700;
}

.uvq05-ch .row {
  display: flex;
  justify-content: space-between;
  align-items: flex-end;
  padding: .6em .8em .5em;
  border-radius: 1em;
  background: color-mix(in srgb,var(--fg) 6%,transparent);
  transition: background calc(0.4s / var(--k)) cubic-bezier(.25,.1,.25,1);
}

.uvq05-ch label {
  position: relative;
  padding: .15em;
  border-radius: .6em;
  cursor: pointer;
  --f: color-mix(in srgb,var(--fg) 22%,transparent);
}

.uvq05-ch input {
  position: absolute;
  opacity: 0;
  width: 1px;
  height: 1px;
  margin: 0;
  pointer-events: none;
}

.uvq05-ch svg {
  display: block;
  width: 2em;
  height: 3.3em;
  transform-origin: 50% 10%;
  transition: transform calc(0.35s / var(--k)) cubic-bezier(.34,1.56,.64,1),filter calc(0.3s / var(--k)) cubic-bezier(.25,.1,.25,1);
}

.uvq05-ch label:nth-of-type(odd) svg {
  rotate: -9deg;
}

.uvq05-ch label:nth-of-type(even) svg {
  rotate: 8deg;
}

.uvq05-ch svg .bd {
  fill: var(--f);
  transition: fill calc(0.3s / var(--k)) cubic-bezier(.25,.1,.25,1);
}

.uvq05-ch label:hover svg {
  transform: translateY(-.25em) scale(1.06);
}

.uvq05-ch label:active svg {
  transform: scale(.88);
}

.uvq05-ch label:has(input:focus-visible) {
  outline: 2px solid var(--c1);
  outline-offset: 3px;
}

.uvq05-ch label:has(input:checked) svg {
  animation: uvq05-chw calc(1.8s / var(--k)) cubic-bezier(.25,.1,.25,1) infinite;
}

.uvq05-ch:has(label:nth-of-type(1) input:checked) {
  --w: 20%;
}

.uvq05-ch:has(label:nth-of-type(1) input:checked) label:nth-of-type(-n+1) {
  --f: var(--h);
}

.uvq05-ch:has(label:nth-of-type(1) input:checked) .lv span:nth-child(1) {
  display: inline-block;
}

.uvq05-ch:has(label:nth-of-type(2) input:checked) {
  --w: 40%;
}

.uvq05-ch:has(label:nth-of-type(2) input:checked) label:nth-of-type(-n+2) {
  --f: var(--h);
}

.uvq05-ch:has(label:nth-of-type(2) input:checked) .lv span:nth-child(2) {
  display: inline-block;
}

.uvq05-ch:has(label:nth-of-type(3) input:checked) {
  --w: 60%;
}

.uvq05-ch:has(label:nth-of-type(3) input:checked) label:nth-of-type(-n+3) {
  --f: var(--h);
}

.uvq05-ch:has(label:nth-of-type(3) input:checked) .lv span:nth-child(3) {
  display: inline-block;
}

.uvq05-ch:has(label:nth-of-type(4) input:checked) {
  --w: 80%;
}

.uvq05-ch:has(label:nth-of-type(4) input:checked) label:nth-of-type(-n+4) {
  --f: var(--h);
}

.uvq05-ch:has(label:nth-of-type(4) input:checked) .lv span:nth-child(4) {
  display: inline-block;
}

.uvq05-ch:has(label:nth-of-type(5) input:checked) {
  --w: 100%;
}

.uvq05-ch:has(label:nth-of-type(5) input:checked) label:nth-of-type(-n+5) {
  --f: var(--h);
}

.uvq05-ch:has(label:nth-of-type(5) input:checked) .lv span:nth-child(5) {
  display: inline-block;
}

@media (hover:hover) {
  .uvq05-ch .row:hover label:is(:hover,:has(~ label:hover)) .bd {
    fill: var(--h);
  }
  .uvq05-ch .row:hover label:hover ~ label .bd {
    fill: color-mix(in srgb,var(--fg) 22%,transparent);
  }
}

.uvq05-ch:has(label:nth-of-type(5) input:checked) .row {
  background: color-mix(in srgb,#ff5a1f 16%,transparent);
}

.uvq05-ch:has(label:nth-of-type(5) input:checked) svg {
  filter: drop-shadow(0 0 .35em #ff5a1f);
}

.uvq05-ch .bar {
  position: relative;
  height: .42em;
  margin: .75em .2em 0;
  border-radius: 1em;
  overflow: hidden;
  background: linear-gradient(90deg,var(--c2),#f7c548 25%,#f06b1f 55%,var(--c1) 78%,#a3121f);
}

.uvq05-ch .bar i {
  position: absolute;
  right: 0;
  top: 0;
  bottom: 0;
  width: calc(100% - var(--w));
  background: color-mix(in srgb,var(--fg) 12%,var(--bg));
  transition: width calc(0.5s / var(--k)) cubic-bezier(.22,1,.36,1);
}

.uvq05-ch .lv {
  height: 1.4em;
  margin: .55em .2em 0;
  font-weight: 800;
}

.uvq05-ch .lv span {
  display: none;
  animation: uvq05-chp calc(0.35s / var(--k)) cubic-bezier(.34,1.56,.64,1);
}

@keyframes uvq05-chw {
  0%,62%,100% {
    transform: none;
  }
  70% {
    transform: rotate(9deg);
  }
  80% {
    transform: rotate(-7deg);
  }
  90% {
    transform: rotate(3deg);
  }
}

@keyframes uvq05-chp {
  from {
    transform: translateY(.4em) scale(.8);
    opacity: 0;
  }
}

@media (prefers-reduced-motion:reduce) {
  .uvq05-ch,.uvq05-ch *,.uvq05-ch *::before,.uvq05-ch *::after {
    animation-duration: .01ms!important;
    animation-iteration-count: 1!important;
    transition-duration: .01ms!important;
  }
}

