css:
.uvq05-mo {
  --c1: #f6e7b8;
  --c2: #18213f;
  --s: 16px;
  /* tamaño */
  --k: 1;
  /* velocidad */
  --fg: #1d1d1f;
  /* texto */
  --bg: #f5f5f7;
  /* fondo */
}

.uvq05-mo {
  font-family: -apple-system,BlinkMacSystemFont,"SF Pro Text","Inter",system-ui,sans-serif;
  font-size: var(--s);
  color: var(--fg);
  -webkit-tap-highlight-color: transparent;
  border: 0;
  margin: 0;
  padding: 0;
  min-width: 0;
  position: relative;
  width: 18em;
  padding: 1em 1em .9em;
  border-radius: 1.2em;
  color: #eef0f7;
  background: radial-gradient(1px 1px at 12% 18%,#fff 60%,transparent),radial-gradient(1px 1px at 78% 10%,#fff 60%,transparent),radial-gradient(1.5px 1.5px at 52% 6%,#fff 60%,transparent),radial-gradient(1px 1px at 33% 52%,#fff 60%,transparent),radial-gradient(1px 1px at 90% 58%,#fff 60%,transparent),radial-gradient(1px 1px at 62% 92%,#fff 60%,transparent),linear-gradient(170deg,color-mix(in srgb,var(--c2) 80%,#5b6aa8),var(--c2) 65%);
  box-shadow: 0 1.4em 2.6em -1.4em rgba(0,0,0,.6);
  counter-reset: uvq05-mo;
}

.uvq05-mo::before {
  content: "";
  position: absolute;
  inset: 0;
  border-radius: inherit;
  background: radial-gradient(1.5px 1.5px at 22% 40%,#fff 60%,transparent),radial-gradient(1px 1px at 70% 44%,#fff 60%,transparent),radial-gradient(1.5px 1.5px at 44% 96%,#fff 60%,transparent),radial-gradient(1px 1px at 6% 80%,#fff 60%,transparent);
  animation: uvq05-mot calc(2.6s / var(--k)) ease-in-out infinite alternate;
  pointer-events: none;
}

.uvq05-mo legend {
  float: left;
  width: 100%;
  padding: 0;
  margin: 0 0 .9em;
  font-weight: 700;
}

.uvq05-mo .gr {
  clear: both;
  position: relative;
  display: grid;
  grid-template-columns: repeat(4,1fr);
  gap: .7em .3em;
}

.uvq05-mo label {
  position: relative;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: .4em;
  cursor: pointer;
}

.uvq05-mo input {
  position: absolute;
  opacity: 0;
  width: 1px;
  height: 1px;
  margin: 0;
  pointer-events: none;
}

.uvq05-mo input:checked {
  counter-increment: uvq05-mo;
}

.uvq05-mo .mn {
  display: block;
  width: 2.8em;
  height: 2.8em;
  border-radius: 50%;
  transition: transform calc(0.4s / var(--k)) cubic-bezier(.34,1.56,.64,1),filter calc(0.35s / var(--k)) cubic-bezier(.25,.1,.25,1);
}

.uvq05-mo svg {
  display: block;
  width: 100%;
  height: 100%;
  overflow: visible;
}

.uvq05-mo .dk {
  fill: color-mix(in srgb,var(--c2) 62%,#8a93b8);
  transition: stroke calc(0.3s / var(--k)) cubic-bezier(.25,.1,.25,1);
}

.uvq05-mo .lt {
  fill: color-mix(in srgb,var(--c1) 45%,#7d86ab);
  transition: fill calc(0.35s / var(--k)) cubic-bezier(.25,.1,.25,1);
}

.uvq05-mo .cr {
  fill: rgba(0,0,0,.13);
}

.uvq05-mo .nm {
  min-height: 2.3em;
  font-size: .6em;
  font-weight: 600;
  line-height: 1.15;
  text-align: center;
  color: rgba(238,240,247,.62);
  transition: color calc(0.3s / var(--k)) cubic-bezier(.25,.1,.25,1);
}

.uvq05-mo label:hover .mn {
  transform: scale(1.08);
}

.uvq05-mo label:active .mn {
  transform: scale(.9);
}

.uvq05-mo input:checked+.mn {
  filter: drop-shadow(0 0 .45em color-mix(in srgb,var(--c1) 75%,transparent));
}

.uvq05-mo input:checked+.mn .lt {
  fill: var(--c1);
}

.uvq05-mo input:checked+.mn .dk {
  stroke: var(--c1);
  stroke-width: 1.2;
}

.uvq05-mo input:checked~.nm {
  color: #fff;
  font-weight: 800;
}

.uvq05-mo input:focus-visible+.mn {
  outline: 2px solid var(--c1);
  outline-offset: .3em;
}

.uvq05-mo .ct {
  position: relative;
  margin: .3em 0 0;
  font-size: .75em;
  color: rgba(238,240,247,.68);
}

.uvq05-mo .n::before {
  content: counter(uvq05-mo);
  font-weight: 800;
  color: #fff;
}

@keyframes uvq05-mot {
  from {
    opacity: .15;
  }
  to {
    opacity: 1;
  }
}

@media (prefers-reduced-motion:reduce) {
  .uvq05-mo,.uvq05-mo *,.uvq05-mo *::before,.uvq05-mo *::after {
    animation-duration: .01ms!important;
    animation-iteration-count: 1!important;
    transition-duration: .01ms!important;
  }
}

