.uvq05-tt {
  --c1: #475569;
  --c2: #dbeafe;
  --s: 16px;
  /* tamaño */
  --k: 1;
  /* velocidad */
  --fg: #1d1d1f;
  /* texto */
  --bg: #f5f5f7;
  /* fondo */
}

.uvq05-tt {
  font-family: -apple-system,BlinkMacSystemFont,"SF Pro Text","Inter",system-ui,sans-serif;
  font-size: var(--s);
  color: var(--fg);
  -webkit-tap-highlight-color: transparent;
  border: 0;
  margin: 0;
  padding: 0;
  min-width: 0;
  width: 17em;
  counter-reset: uvq05-tt;
}

.uvq05-tt legend {
  padding: 0;
  margin: 0 0 .8em;
  font-weight: 700;
}

.uvq05-tt .rk {
  position: relative;
  display: flex;
  justify-content: space-around;
  padding: .7em .4em .6em;
  border-radius: .9em;
  background: color-mix(in srgb,var(--fg) 6%,transparent);
}

.uvq05-tt .rk::after {
  content: "";
  position: absolute;
  left: .4em;
  right: .4em;
  bottom: 1.95em;
  height: .45em;
  border-radius: .2em;
  background: linear-gradient(color-mix(in srgb,var(--c1) 60%,#fff),var(--c1));
  box-shadow: 0 .3em .4em -.2em rgba(0,0,0,.4);
  pointer-events: none;
}

.uvq05-tt .bar {
  position: absolute;
  left: .4em;
  right: .4em;
  top: 1.7em;
  z-index: 2;
  height: .5em;
  border-radius: .2em;
  background: linear-gradient(color-mix(in srgb,var(--c1) 55%,#fff),var(--c1));
  box-shadow: 0 .2em .3em rgba(0,0,0,.3);
  pointer-events: none;
}

.uvq05-tt label {
  position: relative;
  z-index: 1;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: .75em;
  cursor: pointer;
}

.uvq05-tt input {
  position: absolute;
  opacity: 0;
  width: 1px;
  height: 1px;
  margin: 0;
  pointer-events: none;
}

.uvq05-tt input:checked {
  counter-increment: uvq05-tt;
}

.uvq05-tt .tb {
  position: relative;
  display: block;
  width: 1.35em;
  height: 5.4em;
  border-radius: .15em .15em .7em .7em;
  overflow: hidden;
  background: linear-gradient(90deg,rgba(255,255,255,.6),rgba(255,255,255,.1) 35%,rgba(255,255,255,0) 60%,rgba(255,255,255,.35)),color-mix(in srgb,var(--c2) 40%,transparent);
  box-shadow: inset 0 0 0 1.5px color-mix(in srgb,var(--fg) 28%,transparent);
  transition: transform calc(0.4s / var(--k)) cubic-bezier(.34,1.56,.64,1);
}

.uvq05-tt .lq {
  position: absolute;
  left: 0;
  right: 0;
  bottom: 0;
  height: 0;
  background: linear-gradient(90deg,color-mix(in srgb,var(--l) 78%,#000),var(--l) 40%,color-mix(in srgb,var(--l) 70%,#fff));
  transition: height calc(0.8s / var(--k)) cubic-bezier(.22,1,.36,1);
}

.uvq05-tt .lq::before {
  content: "";
  position: absolute;
  left: 0;
  right: 0;
  top: -.15em;
  height: .3em;
  border-radius: 50%;
  background: color-mix(in srgb,var(--l) 55%,#fff);
}

.uvq05-tt .bu {
  position: absolute;
  left: 0;
  right: 0;
  bottom: 0;
  height: 68%;
  background: radial-gradient(circle,rgba(255,255,255,.85) 0 .07em,transparent .09em) 30% 0/.6em 1.6em,radial-gradient(circle,rgba(255,255,255,.7) 0 .05em,transparent .07em) 75% 0/.5em 2.2em;
  opacity: 0;
  transition: opacity calc(0.3s / var(--k)) cubic-bezier(.25,.1,.25,1);
  animation: uvq05-ttb calc(1.6s / var(--k)) linear infinite;
}

.uvq05-tt .nm {
  font-size: .66em;
  font-weight: 600;
  color: color-mix(in srgb,var(--fg) 58%,transparent);
  transition: color calc(0.3s / var(--k)) cubic-bezier(.25,.1,.25,1);
}

.uvq05-tt label:hover .tb {
  transform: translateY(-.2em) rotate(-3deg);
}

.uvq05-tt label:active .tb {
  transform: scale(.94);
}

.uvq05-tt input:checked+.tb .lq {
  height: 72%;
}

.uvq05-tt input:checked+.tb .bu {
  opacity: 1;
  transition-delay: calc(0.5s / var(--k));
}

.uvq05-tt input:checked~.nm {
  color: var(--fg);
  font-weight: 800;
}

.uvq05-tt input:focus-visible+.tb {
  outline: 2px solid var(--c1);
  outline-offset: 3px;
}

.uvq05-tt .ct {
  margin: .8em 0 0;
  font-size: .8em;
  color: color-mix(in srgb,var(--fg) 58%,transparent);
}

.uvq05-tt .n::before {
  content: counter(uvq05-tt);
  font-weight: 800;
  color: var(--fg);
}

