  position: relative;
  cursor: pointer;
}

.uvq05-hb input {
  position: absolute;
  opacity: 0;
  width: 1px;
  height: 1px;
  margin: 0;
  pointer-events: none;
}

.uvq05-hb input:checked {
  counter-increment: uvq05-hb;
}

.uvq05-hb .sh {
  position: relative;
  display: flex;
  flex-direction: column;
  align-items: center;
  padding: .6em .3em .45em;
