  box-shadow: 0 .1em .2em rgba(0,0,0,.18),0 .6em 1em -.7em rgba(0,0,0,.4);
  transform: rotate(var(--r));
  transition: transform calc(0.45s / var(--k)) cubic-bezier(.34,1.56,.64,1),box-shadow calc(0.45s / var(--k)) cubic-bezier(.25,.1,.25,1);
}

.uvq05-hb .tp {
  position: absolute;
  top: -.3em;
  left: 50%;
  width: 1.8em;
  height: .55em;
  margin-left: -.9em;
  background: rgba(235,225,190,.75);
  box-shadow: 0 0 0 1px rgba(0,0,0,.04);
  transform: rotate(calc(var(--r) * -2));
}

.uvq05-hb .lf {
  display: block;
  width: 2.6em;
  height: 3.25em;
  overflow: visible;
}

.uvq05-hb .lf .b {
  fill: #9a8656;
  transition: fill calc(0.5s / var(--k)) cubic-bezier(.25,.1,.25,1);
}

.uvq05-hb .lf .v {
  fill: none;
  stroke: #6e5d36;
  stroke-width: 1;
  stroke-linecap: round;
  stroke-linejoin: round;
  transition: stroke calc(0.5s / var(--k)) cubic-bezier(.25,.1,.25,1);
}

.uvq05-hb .lf .s {
  fill: none;
  stroke: #9a8656;
  stroke-width: 1.6;
  stroke-linecap: round;
  transition: stroke calc(0.5s / var(--k)) cubic-bezier(.25,.1,.25,1);
}

.uvq05-hb .nm {
  position: relative;
  margin-top: .35em;
  padding: 0 .2em;
  font: italic .62em Georgia,"Iowan Old Style","Times New Roman",serif;
  color: #4a3f2a;
}

.uvq05-hb .pc {
  position: absolute;
  left: -.6em;
  right: -.6em;
  top: -.35em;
  width: calc(100% + 1.2em);
  height: calc(100% + .7em);
  overflow: visible;
  fill: none;
  stroke: #5b5b5b;
  stroke-width: 1.4;
  stroke-linecap: round;
  stroke-dasharray: 1;
  stroke-dashoffset: 1;
  vector-effect: non-scaling-stroke;
  transition: stroke-dashoffset calc(0.6s / var(--k)) cubic-bezier(.25,.1,.25,1);
}

.uvq05-hb label:hover .sh {
  transform: rotate(0) translateY(-.15em);
}

.uvq05-hb label:active .sh {
  transform: scale(.95);
}

.uvq05-hb input:checked+.sh {
  transform: rotate(0) translateY(-.2em);
