}

.uvq05-hb input:checked+.sh .lf .s {
  stroke: var(--c1);
}

.uvq05-hb input:checked+.sh .pc {
  stroke-dashoffset: 0;
}

.uvq05-hb input:focus-visible+.sh {
  outline: 2px solid var(--c1);
