css:
.uvq05-cp {
  --c1: #c2410c;
  --c2: #fbf3df;
  --s: 16px;
  /* tamaño */
  --k: 1;
  /* velocidad */
  --fg: #1d1d1f;
  /* texto */
  --bg: #f5f5f7;
  /* fondo */
}

.uvq05-cp {
  font-family: -apple-system,BlinkMacSystemFont,"SF Pro Text","Inter",system-ui,sans-serif;
  font-size: var(--s);
  color: var(--fg);
  -webkit-tap-highlight-color: transparent;
  border: 0;
  margin: 0;
  padding: 0;
  min-width: 0;
  width: 13em;
  counter-reset: uvq05-cp;
}

.uvq05-cp legend {
  padding: 0;
  margin: 0 0 .8em;
  font-weight: 700;
}

.uvq05-cp .rs {
  position: relative;
  width: 12.5em;
  height: 12.5em;
  margin: 0 auto;
  border-radius: 50%;
  background: radial-gradient(circle,transparent 60%,rgba(122,90,42,.12)),var(--c2);
  box-shadow: inset 0 0 0 .45em color-mix(in srgb,var(--c2) 80%,#7a5a2a),inset 0 0 0 .5em rgba(0,0,0,.25),0 1em 2em -1em rgba(0,0,0,.55);
  --a: 90deg;
}

.uvq05-cp .rs::before {
  content: "";
  position: absolute;
  inset: .5em;
  border-radius: 50%;
  background: repeating-conic-gradient(rgba(90,64,32,.6) 0 .7deg,transparent .7deg 7.5deg);
  -webkit-mask: radial-gradient(farthest-side,transparent calc(100% - .45em),#000 calc(100% - .45em + 1px));
  mask: radial-gradient(farthest-side,transparent calc(100% - .45em),#000 calc(100% - .45em + 1px));
  pointer-events: none;
}

.uvq05-cp .dl {
  position: absolute;
  inset: 1em;
  border-radius: 50%;
  overflow: hidden;
}

.uvq05-cp label {
  position: absolute;
  inset: 0;
  transform: rotate(calc(var(--i) * 45deg));
  clip-path: polygon(50% 50%,29.3% 0,70.7% 0);
  cursor: pointer;
}

.uvq05-cp input {
  position: absolute;
  opacity: 0;
  width: 1px;
  height: 1px;
  margin: 0;
  pointer-events: none;
}

.uvq05-cp input:checked {
  counter-increment: uvq05-cp;
}

.uvq05-cp .w {
  position: absolute;
  inset: 0;
  background: rgba(122,90,42,.05);
  transition: background calc(0.3s / var(--k)) cubic-bezier(.25,.1,.25,1);
}

.uvq05-cp label:nth-of-type(even) .w {
  background: rgba(122,90,42,.11);
}

.uvq05-cp label:hover .w {
  background: color-mix(in srgb,var(--c1) 22%,transparent);
}

.uvq05-cp input:checked+.w {
  background: radial-gradient(circle,transparent 0 21%,color-mix(in srgb,var(--c1) 82%,transparent) 21.5%);
  animation: uvq05-cpw calc(0.45s / var(--k)) cubic-bezier(.34,1.56,.64,1);
}

.uvq05-cp input:focus-visible+.w {
  background: color-mix(in srgb,var(--c1) 40%,transparent);
}

.uvq05-cp input:checked:focus-visible+.w {
  background: radial-gradient(circle,transparent 0 21%,color-mix(in srgb,var(--c1) 70%,#000) 21.5%);
}

.uvq05-cp .rs:has(input:focus-visible) {
  outline: 2px solid var(--c1);
  outline-offset: 3px;
}

.uvq05-cp label:active .w {
  opacity: .8;
}

.uvq05-cp .st {
  position: absolute;
  left: 50%;
  top: 50%;
  width: 5.4em;
  height: 5.4em;
  margin: -2.7em;
  pointer-events: none;
  opacity: .9;
}

.uvq05-cp .cd {
  position: absolute;
  z-index: 1;
  font-size: .52em;
  font-weight: 800;
  letter-spacing: .1em;
  text-transform: uppercase;
  color: #4a3418;
  pointer-events: none;
}

.uvq05-cp .cn {
  top: 2.6em;
  left: 50%;
  translate: -50% 0;
}

.uvq05-cp .cs {
  bottom: 2.6em;
  left: 50%;
  translate: -50% 0;
}

.uvq05-cp .ce {
  right: 2.3em;
  top: 50%;
  translate: 0 -50%;
}

.uvq05-cp .cw {
  left: 2.3em;
  top: 50%;
  translate: 0 -50%;
}

.uvq05-cp .nd {
  position: absolute;
  left: 50%;
  top: 50%;
  width: .55em;
  height: 6em;
  margin: -3em 0 0 -.275em;
  background: linear-gradient(var(--c1) 50%,#2f2f31 50%);
  clip-path: polygon(50% 0,100% 50%,50% 100%,0 50%);
  transform: rotate(var(--a));
  transition: transform calc(0.9s / var(--k)) cubic-bezier(.34,1.56,.64,1);
  pointer-events: none;
  filter: drop-shadow(0 .1em .1em rgba(0,0,0,.3));
}

.uvq05-cp .hub {
  position: absolute;
  left: 50%;
  top: 50%;
  width: .8em;
  height: .8em;
  margin: -.4em;
  border-radius: 50%;
  background: radial-gradient(circle at 35% 30%,#fff3c4,#b8862b 60%,#6b4a14);
  pointer-events: none;
}

.uvq05-cp .ct {
  margin: .8em 0 0;
  font-size: .8em;
  text-align: center;
  color: color-mix(in srgb,var(--fg) 58%,transparent);
}

.uvq05-cp .n::before {
  content: counter(uvq05-cp);
  font-weight: 800;
  color: var(--fg);
}

@keyframes uvq05-cpw {
  from {
    transform: scale(.4);
  }
}

@media (prefers-reduced-motion:reduce) {
  .uvq05-cp,.uvq05-cp *,.uvq05-cp *::before,.uvq05-cp *::after {
    animation-duration: .01ms!important;
    animation-iteration-count: 1!important;
    transition-duration: .01ms!important;
  }
}

