.uvq05-kb {
  --c1: #36d67a;
  --c2: #ff7a1a;
  --s: 16px;
  /* tamaño */
  --k: 1;
  /* velocidad */
  --fg: #1d1d1f;
  /* texto */
  --bg: #f5f5f7;
  /* fondo */
}

.uvq05-kb {
  font-family: -apple-system,BlinkMacSystemFont,"SF Pro Text","Inter",system-ui,sans-serif;
  font-size: var(--s);
  color: var(--fg);
  -webkit-tap-highlight-color: transparent;
  width: 15em;
  padding: .8em;
  border-radius: 1em;
  background: linear-gradient(160deg,#34363b,#1f2024);
  box-shadow: inset 0 1px 0 rgba(255,255,255,.1),0 1.4em 2.6em -1.4em rgba(0,0,0,.65);
}

.uvq05-kb .ol {
  display: flex;
  flex-direction: column;
  gap: .2em;
  margin: 0 0 .8em;
