  transition: fill calc(0.35s / var(--k)) cubic-bezier(.25,.1,.25,1),stroke-width calc(0.3s / var(--k)) cubic-bezier(.25,.1,.25,1);
}

.uvq05-vn .r {
  color: var(--fg);
  opacity: 0;
  transition: opacity calc(0.35s / var(--k)) cubic-bezier(.25,.1,.25,1);
}

