css:
.uvq05-sh {
  --c1: #8b5e34;
  --c2: #3f7d4e;
  --s: 16px;
  /* tamaño */
  --k: 1;
  /* velocidad */
  --fg: #1d1d1f;
  /* texto */
  --bg: #f5f5f7;
  /* fondo */
}

.uvq05-sh {
  font-family: -apple-system,BlinkMacSystemFont,"SF Pro Text","Inter",system-ui,sans-serif;
  font-size: var(--s);
  color: var(--fg);
  -webkit-tap-highlight-color: transparent;
  width: 16em;
}

.uvq05-sh .hd {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: .5em;
  margin-bottom: .8em;
}

.uvq05-sh .lb {
  font-weight: 700;
}

.uvq05-sh .sg {
  display: flex;
  padding: .2em;
  border-radius: .7em;
  background: color-mix(in srgb,var(--fg) 6%,transparent);
}

.uvq05-sh label {
  position: relative;
  cursor: pointer;
}

.uvq05-sh input {
  position: absolute;
  opacity: 0;
  width: 1px;
  height: 1px;
  margin: 0;
  pointer-events: none;
}

.uvq05-sh .sg span {
  display: block;
  padding: .4em .65em;
  border-radius: .55em;
  font-size: .75em;
  font-weight: 700;
  color: color-mix(in srgb,var(--fg) 58%,transparent);
  transition: background calc(0.25s / var(--k)) cubic-bezier(.25,.1,.25,1),color calc(0.25s / var(--k)) cubic-bezier(.25,.1,.25,1);
}

.uvq05-sh label:hover span {
  color: var(--fg);
}

.uvq05-sh label:active span {
  transform: scale(.95);
}

.uvq05-sh input:checked+span {
  color: #fff;
  background: var(--c1);
}

.uvq05-sh input:focus-visible+span {
  outline: 2px solid var(--c1);
  outline-offset: 3px;
}

.uvq05-sh .sf {
  position: relative;
  height: 7em;
  border-radius: .6em .6em .2em .2em;
  background: linear-gradient(transparent 60%,color-mix(in srgb,var(--c1) 10%,transparent)),color-mix(in srgb,var(--fg) 6%,transparent);
}

.uvq05-sh .sf::after {
  content: "";
  position: absolute;
  left: 0;
  right: 0;
  bottom: 0;
  height: .55em;
  border-radius: .15em;
  background: linear-gradient(color-mix(in srgb,var(--c1) 70%,#fff),var(--c1));
  box-shadow: 0 .5em .8em -.3em rgba(0,0,0,.45);
}

.uvq05-sh .bk {
  position: absolute;
  bottom: .55em;
  left: calc(1em + var(--x0));
  width: var(--w);
  height: var(--h);
  border-radius: .12em .12em .05em .05em;
  background: linear-gradient(90deg,rgba(0,0,0,.25),rgba(255,255,255,.18) 20%,transparent 45%,rgba(0,0,0,.2)),linear-gradient(transparent .5em,rgba(255,220,150,.8) .5em .62em,transparent .62em .8em,rgba(255,220,150,.8) .8em .86em,transparent .86em calc(100% - .7em),rgba(255,220,150,.7) calc(100% - .7em) calc(100% - .6em),transparent calc(100% - .6em)),var(--b);
  box-shadow: inset 0 0 0 1px rgba(0,0,0,.18);
  transform-origin: 50% 100%;
  transition: left calc(0.7s / var(--k)) cubic-bezier(.22,1,.36,1);
  transition-delay: calc(var(--d) * 0.03s / var(--k));
  animation: uvq05-sha calc(0.7s / var(--k)) cubic-bezier(.22,1,.36,1) both;
  animation-delay: calc(var(--d) * 0.03s / var(--k));
}

.uvq05-sh .bk b {
  position: absolute;
  left: 50%;
  top: 50%;
  font: 700 .45em ui-monospace,SFMono-Regular,Menlo,Consolas,monospace;
  color: var(--t,rgba(255,255,255,.85));
  writing-mode: vertical-rl;
  transform: translate(-50%,-50%) rotate(180deg);
}

.uvq05-sh:has(.sg label:nth-of-type(2) input:checked) .bk {
  left: calc(1em + var(--x1));
  animation-name: uvq05-shb;
}

.uvq05-sh:has(.sg label:nth-of-type(3) input:checked) .bk {
  left: calc(1em + var(--x2));
  animation-name: uvq05-shc;
}

.uvq05-sh .pt {
  position: absolute;
  right: 1em;
  bottom: .55em;
  width: 1.8em;
  height: 1.6em;
  border-radius: .15em .15em .5em .5em;
  background: linear-gradient(#c96f45,#a8532f);
}

.uvq05-sh .pt i {
  position: absolute;
  bottom: 1.4em;
  left: 50%;
  width: .7em;
  height: 1.9em;
  margin-left: -.35em;
  border-radius: 50% 50% 50% 50%/80% 80% 20% 20%;
  background: var(--c2);
  transform-origin: 50% 100%;
}

.uvq05-sh .pt i:nth-child(1) {
  transform: rotate(-30deg);
}

.uvq05-sh .pt i:nth-child(3) {
  transform: rotate(32deg);
  height: 1.6em;
}

.uvq05-sh .pt i:nth-child(2) {
  height: 2.3em;
  background: color-mix(in srgb,var(--c2) 80%,#fff);
}

@keyframes uvq05-sha {
  40% {
    transform: translateY(-1.1em) rotate(-4deg);
  }
}

@keyframes uvq05-shb {
  40% {
    transform: translateY(-1.1em) rotate(-4deg);
  }
}

@keyframes uvq05-shc {
  40% {
    transform: translateY(-1.1em) rotate(-4deg);
  }
}

@media (prefers-reduced-motion:reduce) {
  .uvq05-sh,.uvq05-sh *,.uvq05-sh *::before,.uvq05-sh *::after {
    animation-duration: .01ms!important;
    animation-iteration-count: 1!important;
    transition-duration: .01ms!important;
  }
}

